window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["meta"]={html:"<div class=\"own-meta\">\n  <div class=\"mt-promo\">\n    <span>Get 25% off the first year of Northwind Network</span>\n    <a href=\"#pricing\">See the offer &rarr;</a>\n  </div>\n\n  <header class=\"mt-nav\">\n    <a class=\"mt-logo\" href=\"#\" aria-label=\"Northwind home\">\n      <span class=\"mt-mark\" aria-hidden=\"true\"></span>\n      <span class=\"mt-logo-word\">Northwind</span>\n    </a>\n    <nav class=\"mt-tabs\" aria-label=\"Categories\">\n      <a href=\"#shop\" class=\"mt-tab is-active\" aria-current=\"page\">Boards</a>\n      <a href=\"#shop\" class=\"mt-tab\">Regions</a>\n      <a href=\"#shop\" class=\"mt-tab\">Pricing</a>\n      <a href=\"#shop\" class=\"mt-tab\">Apps</a>\n    </nav>\n    <div class=\"mt-nav-right\">\n      <label class=\"mt-search\">\n        <span class=\"mt-sr\">Search</span>\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-4-4\"/></svg>\n        <input type=\"search\" placeholder=\"Search boards\" autocomplete=\"off\">\n      </label>\n      <a class=\"mt-icon-btn\" href=\"#\" aria-label=\"Account\">\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 20c1.6-3.6 4.6-5.4 8-5.4S18.4 16.4 20 20\"/></svg>\n      </a>\n      <a class=\"mt-icon-btn\" href=\"#\" aria-label=\"Cart\">\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 6h2l2 11h10M8 9h11l-1.6 6H9\"/><circle cx=\"9\" cy=\"20\" r=\"1.4\"/><circle cx=\"17\" cy=\"20\" r=\"1.4\"/></svg>\n      </a>\n    </div>\n  </header>\n\n  <section class=\"mt-hero\" aria-labelledby=\"mtHeroH\">\n    <div class=\"mt-hero-photo\" aria-hidden=\"true\">\n      <div class=\"mt-hero-panel\">\n        <div class=\"mt-hero-panel-head\"><span>Throughput</span><span>Live</span></div>\n        <div class=\"mt-hero-bars\">\n          <span style=\"--h:44%\"></span><span style=\"--h:62%\"></span><span style=\"--h:53%\"></span>\n          <span style=\"--h:78%\"></span><span style=\"--h:67%\"></span><span style=\"--h:92%\"></span>\n          <span style=\"--h:81%\"></span><span style=\"--h:70%\"></span>\n        </div>\n      </div>\n    </div>\n    <div class=\"mt-hero-overlay\">\n      <h1 id=\"mtHeroH\" class=\"mt-h1\">Operations, built for clarity.</h1>\n      <p class=\"mt-hero-sub\">One board for every dock, region and price tier &mdash; modelled live,\n        ready to share before the doors open.</p>\n      <div class=\"mt-hero-cta\">\n        <a class=\"mt-btn mt-btn-primary\" href=\"#shop\">Shop boards</a>\n        <a class=\"mt-btn mt-btn-secondary\" href=\"#details\">Configure yours</a>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"shop\" class=\"mt-sec\" aria-labelledby=\"mtShopH\">\n    <div class=\"mt-sec-head\">\n      <h2 id=\"mtShopH\" class=\"mt-h2\">Designed for operations.</h2>\n      <p class=\"mt-lead\">Pick a starting board and shape it to your network. Photography of the\n        product itself &mdash; no decoration.</p>\n    </div>\n    <div class=\"mt-photo-grid\">\n      <a class=\"mt-photo-card mt-photo-a\" href=\"#details\">\n        <span class=\"mt-badge mt-badge-promo\">Limited time</span>\n        <div class=\"mt-photo-art\" aria-hidden=\"true\"><span class=\"mt-ring\"></span><span class=\"mt-ring\"></span></div>\n        <div class=\"mt-photo-copy\"><h3 class=\"mt-h3\">Throughput board</h3><p>Dock, line and cycle time, live.</p></div>\n      </a>\n      <a class=\"mt-photo-card mt-photo-b\" href=\"#details\">\n        <div class=\"mt-photo-art\" aria-hidden=\"true\">\n          <span class=\"mt-map\"><i></i><i></i><i></i><i></i><i></i></span>\n        </div>\n        <div class=\"mt-photo-copy\"><h3 class=\"mt-h3\">Regional atlas</h3><p>Every territory, one comparison.</p></div>\n      </a>\n    </div>\n    <div class=\"mt-icon-row\">\n      <div class=\"mt-icon-feature\">\n        <span class=\"mt-fi\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 12l4 4 6-8 4 5 4-3\"/></svg></span>\n        <h4 class=\"mt-h4\">Live modelling</h4><p>Refreshes as the data lands.</p>\n      </div>\n      <div class=\"mt-icon-feature\">\n        <span class=\"mt-fi\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"4\"/><path d=\"M8 12l3 3 5-6\"/></svg></span>\n        <h4 class=\"mt-h4\">Free 30-day returns</h4><p>Change plans whenever you need.</p>\n      </div>\n      <div class=\"mt-icon-feature\">\n        <span class=\"mt-fi\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 3l8 4v5c0 4.4-3 8-8 9-5-1-8-4.6-8-9V7z\"/></svg></span>\n        <h4 class=\"mt-h4\">Worry-free warranty</h4><p>Modelled and supported for a year.</p>\n      </div>\n      <div class=\"mt-icon-feature\">\n        <span class=\"mt-fi\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"6\" width=\"18\" height=\"12\" rx=\"3\"/><path d=\"M3 10h18\"/></svg></span>\n        <h4 class=\"mt-h4\">Buy now, pay later</h4><p>Split the annual plan in four.</p>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"details\" class=\"mt-sec mt-pdp\" aria-labelledby=\"mtPdpH\">\n    <h2 id=\"mtPdpH\" class=\"mt-sr\">Configure Northwind Network</h2>\n    <div class=\"mt-pdp-gallery\">\n      <div class=\"mt-thumbs\" role=\"group\" aria-label=\"Views\">\n        <button class=\"mt-thumb is-active\" type=\"button\" aria-label=\"Throughput view\"><span class=\"mt-thumb-art mt-t1\"></span></button>\n        <button class=\"mt-thumb\" type=\"button\" aria-label=\"Region view\"><span class=\"mt-thumb-art mt-t2\"></span></button>\n        <button class=\"mt-thumb\" type=\"button\" aria-label=\"Pricing view\"><span class=\"mt-thumb-art mt-t3\"></span></button>\n        <button class=\"mt-thumb\" type=\"button\" aria-label=\"Digest view\"><span class=\"mt-thumb-art mt-t4\"></span></button>\n      </div>\n      <div class=\"mt-pdp-main\">\n        <span class=\"mt-badge mt-badge-attention\">Almost gone</span>\n        <div class=\"mt-pdp-screen\" aria-hidden=\"true\">\n          <div class=\"mt-pdp-side\"><span class=\"is-on\"></span><span></span><span></span><span></span></div>\n          <div class=\"mt-pdp-canvas\">\n            <div class=\"mt-pdp-axis\"><i style=\"--h:40%\"></i><i style=\"--h:70%\"></i><i style=\"--h:52%\"></i><i style=\"--h:88%\"></i><i style=\"--h:66%\"></i><i style=\"--h:94%\"></i></div>\n            <div class=\"mt-pdp-rows\"><span></span><span></span><span></span></div>\n          </div>\n        </div>\n      </div>\n      <aside class=\"mt-buy\" aria-label=\"Purchase summary\">\n        <p class=\"mt-eyebrow\">Northwind &middot; Network</p>\n        <h3 class=\"mt-h3\">Operations workspace</h3>\n        <p class=\"mt-price\"><b>$49</b><span> /mo per site</span></p>\n        <fieldset class=\"mt-fieldset\">\n          <legend class=\"mt-legend\">Plan</legend>\n          <label class=\"mt-radio\"><input type=\"radio\" name=\"mtPlan\" data-price=\"$49\" checked><span class=\"mt-radio-ui\"></span><span>Depot &mdash; $49</span></label>\n          <label class=\"mt-radio\"><input type=\"radio\" name=\"mtPlan\" data-price=\"$149\"><span class=\"mt-radio-ui\"></span><span>Network &mdash; $149</span></label>\n          <label class=\"mt-radio\"><input type=\"radio\" name=\"mtPlan\" data-price=\"Custom\"><span class=\"mt-radio-ui\"></span><span>Fleet &mdash; Custom</span></label>\n        </fieldset>\n        <fieldset class=\"mt-fieldset\">\n          <legend class=\"mt-legend\">Regions</legend>\n          <div class=\"mt-swatches\" role=\"group\" aria-label=\"Region count\">\n            <button type=\"button\" class=\"mt-swatch is-on\" style=\"--c:#0064e0\" aria-label=\"5 regions\"></button>\n            <button type=\"button\" class=\"mt-swatch\" style=\"--c:#a121ce\" aria-label=\"20 regions\"></button>\n            <button type=\"button\" class=\"mt-swatch\" style=\"--c:#31a24c\" aria-label=\"50 regions\"></button>\n          </div>\n        </fieldset>\n        <button class=\"mt-btn mt-btn-buy\" type=\"button\" data-cart>Add to cart</button>\n        <p class=\"mt-buy-note\"><span class=\"mt-dot-ok\" aria-hidden=\"true\"></span> In stock &middot; Free 30-day returns</p>\n      </aside>\n    </div>\n  </section>\n\n  <section class=\"mt-sec\" aria-labelledby=\"mtTestH\">\n    <div class=\"mt-sec-head\">\n      <h2 id=\"mtTestH\" class=\"mt-h2\">Operations teams, on the record.</h2>\n    </div>\n    <div class=\"mt-testi-grid\">\n      <figure class=\"mt-testi\">\n        <blockquote><p>&ldquo;We cut the Monday reconciliation from three hours to twenty minutes.\n          The region atlas is now the source of truth.&rdquo;</p></blockquote>\n        <figcaption><span class=\"mt-avatar\" aria-hidden=\"true\">MK</span><span><b>Marta Kell</b><br>VP Ops, Tidewell Group</span></figcaption>\n      </figure>\n      <figure class=\"mt-testi\">\n        <blockquote><p>&ldquo;The pricing view finally gave finance and logistics one number to argue\n          about &mdash; and the argument got a lot shorter.&rdquo;</p></blockquote>\n        <figcaption><span class=\"mt-avatar\" aria-hidden=\"true\">DO</span><span><b>Devon Okafor</b><br>Head of Logistics, Kestrel</span></figcaption>\n      </figure>\n      <figure class=\"mt-testi\">\n        <blockquote><p>&ldquo;It reads like a product, not a report. Our directors actually open it\n          before the standup.&rdquo;</p></blockquote>\n        <figcaption><span class=\"mt-avatar\" aria-hidden=\"true\">SA</span><span><b>Suri Alvi</b><br>COO, Meridian Freight</span></figcaption>\n      </figure>\n    </div>\n  </section>\n\n  <footer class=\"mt-foot\">\n    <div class=\"mt-foot-top\">\n      <div class=\"mt-foot-brand\">\n        <span class=\"mt-mark\" aria-hidden=\"true\"></span>\n        <span class=\"mt-logo-word\">Northwind</span>\n      </div>\n      <div class=\"mt-foot-grid\">\n        <div class=\"mt-foot-col\"><h3>Shop</h3><a href=\"#\">Boards</a><a href=\"#\">Regions</a><a href=\"#\">Apps</a></div>\n        <div class=\"mt-foot-col\"><h3>Company</h3><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">News</a></div>\n        <div class=\"mt-foot-col\"><h3>Support</h3><a href=\"#\">Help centre</a><a href=\"#\">Status</a><a href=\"#\">Contact</a></div>\n        <div class=\"mt-foot-col\"><h3>Legal</h3><a href=\"#\">Privacy</a><a href=\"#\">Terms</a><a href=\"#\">Cookies</a></div>\n      </div>\n    </div>\n    <div class=\"mt-foot-bottom\">\n      <span>&copy; 2026 Northwind Analytics</span>\n      <span class=\"mt-foot-links\"><a href=\"#\">Privacy Policy</a><a href=\"#\">Terms of Service</a><a href=\"#\">Cookie Policy</a></span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — own layout in the Meta design language ═════════════════════\n   Stark white canvas, Optimistic VF with ss01/ss02, pill-shaped buttons everywhere\n   (marketing = black, commerce = cobalt), photographic product cards with 32px\n   corners, a dark promo strip above the nav, and a 58/42 PDP with a sticky rail. */\n\n.own-meta {\n  --primary: #0064e0;\n  --primary-deep: #0457cb;\n  --primary-soft: #0091ff;\n  --ink-button: #000000;\n  --canvas: #ffffff;\n  --surface-soft: #f1f4f7;\n  --ink-deep: #0a1317;\n  --ink: #1c1e21;\n  --charcoal: #444950;\n  --slate: #4b4c4f;\n  --steel: #5d6c7b;\n  --stone: #8595a4;\n  --hairline: #ced0d4;\n  --hairline-soft: #dee3e9;\n  --success: #31a24c;\n  --attention: #f2a918;\n  --warning: #f7b928;\n  --critical: #e41e3f;\n  --radius-full: 100px;\n  --shadow-sticky: rgba(20, 22, 26, .3) 0px 1px 4px 0px;\n  --display: 'Optimistic VF', Montserrat, Helvetica, Arial, 'Noto Sans', sans-serif;\n  --gut: clamp(20px, 5cqi, 48px);\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--display);\n  font-size: 16px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n}\n.own-meta *,\n.own-meta *::before,\n.own-meta *::after { box-sizing: border-box; }\n.own-meta h1, .own-meta h2, .own-meta h3, .own-meta h4 { font-family: var(--display); font-feature-settings: 'ss01' 1, 'ss02' 1; }\n.own-meta :focus-visible { outline: 2px solid var(--fb-blue, #1876f2); outline-offset: 2px; border-radius: 6px; }\n.own-meta .mt-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }\n\n/* ── type ────────────────────────────────────────────────────────────────── */\n.own-meta .mt-h1 { font-weight: 500; font-size: clamp(36px, 5.4cqi, 64px); line-height: 1.16; }\n.own-meta .mt-h2 { font-weight: 500; font-size: clamp(28px, 3.4cqi, 48px); line-height: 1.17; }\n.own-meta .mt-h3 { font-weight: 500; font-size: 24px; line-height: 1.25; }\n.own-meta .mt-h4 { font-weight: 700; font-size: 16px; line-height: 1.5; letter-spacing: -.16px; }\n.own-meta .mt-lead { color: var(--charcoal); font-size: 18px; line-height: 1.44; max-width: 54ch; }\n.own-meta .mt-eyebrow { font-size: 12px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--steel); }\n\n/* ── buttons ────────────────────────────────────────────────────────────── */\n.own-meta .mt-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  height: 48px; padding: 0 30px; border: 0; border-radius: var(--radius-full); cursor: pointer;\n  font-family: var(--display); font-size: 14px; font-weight: 700; letter-spacing: -.14px;\n  text-decoration: none; transition: background-color .15s ease;\n}\n.own-meta .mt-btn-primary { background: var(--ink-button); color: #fff; }\n.own-meta .mt-btn-primary:active { background: var(--charcoal); }\n.own-meta .mt-btn-secondary { background: transparent; color: var(--ink-deep); box-shadow: inset 0 0 0 2px var(--ink-deep); }\n.own-meta .mt-btn-buy { background: var(--primary); color: #fff; width: 100%; }\n.own-meta .mt-btn-buy:active { background: var(--primary-deep); }\n\n/* ── promo + nav ─────────────────────────────────────────────────────────── */\n.own-meta .mt-promo { display: flex; align-items: center; justify-content: center; gap: 14px; flex-wrap: wrap; background: var(--ink-deep); color: #fff; padding: 10px 24px; font-size: 14px; font-weight: 700; letter-spacing: -.14px; }\n.own-meta .mt-promo a { color: #fff; text-decoration: underline; }\n.own-meta .mt-nav { position: sticky; top: 68px; z-index: 30; display: flex; align-items: center; gap: 20px; padding: 12px var(--gut); background: rgba(255,255,255,.92); backdrop-filter: blur(10px); border-bottom: 1px solid var(--hairline-soft); }\n.own-meta .mt-logo { display: inline-flex; align-items: center; gap: 10px; text-decoration: none; color: var(--ink-deep); }\n.own-meta .mt-mark { width: 26px; height: 26px; border-radius: 8px; background: var(--primary); display: inline-block; }\n.own-meta .mt-mark::after { content: ''; display: block; width: 100%; height: 100%; border-radius: 8px; background: radial-gradient(60% 60% at 30% 25%, #fff, transparent 60%); opacity: .5; }\n.own-meta .mt-logo-word { font-weight: 700; font-size: 18px; letter-spacing: -.2px; }\n.own-meta .mt-tabs { display: flex; align-items: center; gap: 8px; margin-left: 12px; }\n.own-meta .mt-tab { padding: 8px 16px; border-radius: var(--radius-full); font-size: 14px; font-weight: 700; letter-spacing: -.14px; color: var(--ink); text-decoration: none; border: 1px solid var(--hairline); background: var(--canvas); }\n.own-meta .mt-tab.is-active { background: var(--ink-deep); color: #fff; border-color: var(--ink-deep); }\n.own-meta .mt-nav-right { margin-left: auto; display: flex; align-items: center; gap: 10px; }\n.own-meta .mt-search { display: flex; align-items: center; gap: 8px; height: 40px; padding: 0 18px; border-radius: var(--radius-full); background: var(--surface-soft); }\n.own-meta .mt-search svg { width: 16px; height: 16px; fill: none; stroke: var(--steel); stroke-width: 2; }\n.own-meta .mt-search input { width: 130px; border: 0; background: transparent; color: var(--ink); font: inherit; font-size: 14px; }\n.own-meta .mt-search input::placeholder { color: var(--steel); }\n.own-meta .mt-search input:focus { outline: none; }\n.own-meta .mt-search:focus-within { box-shadow: 0 0 0 2px #1876f2; }\n.own-meta .mt-icon-btn { display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%; background: var(--surface-soft); color: var(--ink); }\n.own-meta .mt-icon-btn svg { width: 19px; height: 19px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n\n/* ── hero ────────────────────────────────────────────────────────────────── */\n.own-meta .mt-hero { position: relative; margin: var(--gut); margin-bottom: 0; border-radius: 32px; overflow: hidden; min-height: clamp(420px, 62cqi, 600px); display: flex; }\n.own-meta .mt-hero-photo { position: absolute; inset: 0; background: radial-gradient(120% 120% at 75% 20%, #24313f 0%, #0d1a22 55%, #060d12 100%); display: flex; align-items: center; justify-content: center; padding: 40px; }\n.own-meta .mt-hero-panel { width: min(560px, 80%); background: rgba(255,255,255,.06); border: 1px solid rgba(255,255,255,.14); border-radius: 24px; padding: 24px; }\n.own-meta .mt-hero-panel-head { display: flex; justify-content: space-between; color: rgba(255,255,255,.72); font-size: 13px; font-weight: 700; letter-spacing: -.14px; margin-bottom: 20px; }\n.own-meta .mt-hero-bars { display: flex; align-items: flex-end; gap: 12px; height: 200px; }\n.own-meta .mt-hero-bars span { flex: 1; height: var(--h); border-radius: 8px 8px 2px 2px; background: linear-gradient(180deg, var(--primary-soft), var(--primary)); opacity: .92; }\n.own-meta .mt-hero-overlay { position: relative; z-index: 2; align-self: flex-end; width: 100%; padding: clamp(32px, 5cqi, 64px); background: linear-gradient(0deg, rgba(6,13,18,.86) 0%, rgba(6,13,18,.4) 55%, transparent 100%); }\n.own-meta .mt-hero-overlay .mt-h1 { color: #fff; max-width: 18ch; }\n.own-meta .mt-hero-sub { color: rgba(255,255,255,.9); font-size: 18px; line-height: 1.44; max-width: 46ch; margin-top: 16px; }\n.own-meta .mt-hero-cta { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 28px; }\n.own-meta .mt-hero-cta .mt-btn-secondary { color: #fff; box-shadow: inset 0 0 0 2px #fff; }\n\n/* ── sections ───────────────────────────────────────────────────────────── */\n.own-meta .mt-sec { padding: clamp(48px, 6cqi, 80px) var(--gut); }\n.own-meta .mt-sec-head { max-width: 680px; margin-bottom: 40px; }\n.own-meta .mt-sec-head .mt-lead { margin-top: 14px; }\n.own-meta .mt-photo-grid { display: grid; grid-template-columns: 1.25fr 1fr; gap: 24px; }\n.own-meta .mt-photo-card { position: relative; display: flex; flex-direction: column; justify-content: flex-end; min-height: 360px; padding: 28px; border-radius: 32px; overflow: hidden; text-decoration: none; color: #fff; }\n.own-meta .mt-photo-a { background: radial-gradient(120% 120% at 25% 15%, #2f7de0 0%, #0457cb 52%, #062b63 100%); }\n.own-meta .mt-photo-b { background: radial-gradient(120% 120% at 70% 20%, #a855f7 0%, #6b2fbf 55%, #2a0f4d 100%); }\n.own-meta .mt-photo-art { position: absolute; inset: 0; display: grid; place-items: center; opacity: .5; pointer-events: none; }\n.own-meta .mt-ring { position: absolute; border: 2px solid rgba(255,255,255,.5); border-radius: 50%; width: 220px; height: 220px; }\n.own-meta .mt-ring:nth-child(2) { width: 320px; height: 320px; border-color: rgba(255,255,255,.28); }\n.own-meta .mt-map { position: relative; width: 380px; height: 220px; }\n.own-meta .mt-map i { position: absolute; width: 58px; height: 58px; border-radius: 50%; background: rgba(255,255,255,.85); }\n.own-meta .mt-map i:nth-child(1) { left: 8%; top: 46%; }\n.own-meta .mt-map i:nth-child(2) { left: 32%; top: 20%; width: 74px; height: 74px; }\n.own-meta .mt-map i:nth-child(3) { left: 56%; top: 52%; }\n.own-meta .mt-map i:nth-child(4) { left: 74%; top: 24%; width: 44px; height: 44px; }\n.own-meta .mt-map i:nth-child(5) { left: 66%; top: 68%; width: 34px; height: 34px; }\n.own-meta .mt-photo-copy { position: relative; z-index: 2; }\n.own-meta .mt-photo-copy p { margin: 6px 0 0; font-size: 14px; color: rgba(255,255,255,.85); }\n.own-meta .mt-badge { position: absolute; top: 24px; left: 24px; z-index: 3; display: inline-flex; padding: 4px 10px; border-radius: var(--radius-full); font-size: 12px; font-weight: 700; }\n.own-meta .mt-badge-promo { background: var(--warning); color: var(--ink-deep); }\n.own-meta .mt-badge-attention { position: static; background: var(--attention); color: #fff; margin-bottom: 14px; }\n.own-meta .mt-icon-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; margin-top: 40px; }\n.own-meta .mt-icon-feature { border: 1px solid var(--hairline-soft); border-radius: 16px; padding: 24px; }\n.own-meta .mt-fi { display: grid; place-items: center; width: 40px; height: 40px; border-radius: 12px; background: var(--surface-soft); margin-bottom: 16px; }\n.own-meta .mt-fi svg { width: 22px; height: 22px; fill: none; stroke: var(--ink-deep); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n.own-meta .mt-icon-feature p { margin: 8px 0 0; font-size: 14px; color: var(--steel); }\n\n/* ── PDP ─────────────────────────────────────────────────────────────────── */\n.own-meta .mt-pdp { background: var(--surface-soft); border-radius: 32px; margin: 0 var(--gut); }\n.own-meta .mt-pdp-gallery { display: grid; grid-template-columns: 88px minmax(0, 1fr) minmax(300px, 380px); gap: clamp(18px, 2.4cqi, 32px); align-items: start; }\n.own-meta .mt-thumbs { display: grid; gap: 12px; }\n.own-meta .mt-thumb { width: 80px; height: 80px; padding: 0; border-radius: 8px; border: 1px solid var(--hairline-soft); background: var(--canvas); cursor: pointer; overflow: hidden; }\n.own-meta .mt-thumb.is-active { border: 2px solid var(--ink-deep); }\n.own-meta .mt-thumb-art { display: block; width: 100%; height: 100%; }\n.own-meta .mt-t1 { background: linear-gradient(135deg, #dfe8f2, #b7c8dd); }\n.own-meta .mt-t2 { background: linear-gradient(135deg, #e6e0f2, #c6b8dd); }\n.own-meta .mt-t3 { background: linear-gradient(135deg, #e0f2e6, #b8ddc6); }\n.own-meta .mt-t4 { background: linear-gradient(135deg, #f2ece0, #ddcfb8); }\n.own-meta .mt-pdp-main { background: var(--canvas); border-radius: 16px; padding: 20px; }\n.own-meta .mt-pdp-screen { display: grid; grid-template-columns: 120px 1fr; gap: 16px; min-height: 360px; }\n.own-meta .mt-pdp-side { display: grid; align-content: start; gap: 10px; padding-top: 8px; }\n.own-meta .mt-pdp-side span { display: block; height: 10px; border-radius: 6px; background: var(--surface-soft); }\n.own-meta .mt-pdp-side span.is-on { background: var(--primary); width: 70%; }\n.own-meta .mt-pdp-side span:nth-child(2) { width: 90%; }\n.own-meta .mt-pdp-side span:nth-child(3) { width: 60%; }\n.own-meta .mt-pdp-canvas { background: var(--surface-soft); border-radius: 12px; padding: 22px; display: grid; align-content: space-between; }\n.own-meta .mt-pdp-axis { display: flex; align-items: flex-end; gap: 14px; height: 180px; }\n.own-meta .mt-pdp-axis i { flex: 1; height: var(--h); border-radius: 6px 6px 2px 2px; background: var(--primary); opacity: .85; }\n.own-meta .mt-pdp-rows { display: grid; gap: 10px; margin-top: 20px; }\n.own-meta .mt-pdp-rows span { display: block; height: 12px; border-radius: 6px; background: var(--hairline-soft); }\n.own-meta .mt-pdp-rows span:nth-child(2) { width: 80%; }\n.own-meta .mt-pdp-rows span:nth-child(3) { width: 60%; }\n.own-meta .mt-buy { background: var(--canvas); border: 1px solid var(--hairline-soft); border-radius: 16px; padding: 24px; box-shadow: var(--shadow-sticky); }\n.own-meta .mt-price { font-size: 28px; font-weight: 500; margin: 10px 0 20px; }\n.own-meta .mt-price span { font-size: 14px; color: var(--steel); font-weight: 400; }\n.own-meta .mt-fieldset { border: 0; padding: 0; margin: 0 0 20px; }\n.own-meta .mt-legend { padding: 0; margin-bottom: 10px; font-size: 12px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--steel); }\n.own-meta .mt-radio { display: flex; align-items: center; gap: 10px; padding: 14px; border: 1px solid rgba(10,19,23,.12); border-radius: 8px; margin-bottom: 8px; cursor: pointer; font-size: 14px; font-weight: 700; letter-spacing: -.14px; }\n.own-meta .mt-radio input { position: absolute; opacity: 0; }\n.own-meta .mt-radio-ui { width: 18px; height: 18px; border-radius: 50%; border: 2px solid var(--hairline); flex: none; }\n.own-meta .mt-radio input:checked + .mt-radio-ui { border-color: var(--primary); box-shadow: inset 0 0 0 4px var(--primary); }\n.own-meta .mt-radio:has(input:checked) { border: 2px solid #0143b5; }\n.own-meta .mt-swatches { display: flex; gap: 12px; }\n.own-meta .mt-swatch { width: 32px; height: 32px; border-radius: 50%; border: 2px solid var(--canvas); background: var(--c); cursor: pointer; box-shadow: 0 0 0 1px var(--hairline); }\n.own-meta .mt-swatch.is-on { box-shadow: 0 0 0 2px var(--ink-deep); }\n.own-meta .mt-buy-note { display: flex; align-items: center; gap: 8px; margin-top: 14px; font-size: 13px; color: var(--steel); }\n.own-meta .mt-dot-ok { width: 8px; height: 8px; border-radius: 50%; background: var(--success); }\n\n/* ── testimonials ────────────────────────────────────────────────────────── */\n.own-meta .mt-testi-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }\n.own-meta .mt-testi { margin: 0; border: 1px solid var(--hairline-soft); border-radius: 16px; padding: 32px; }\n.own-meta .mt-testi blockquote { margin: 0; }\n.own-meta .mt-testi blockquote p { font-size: 16px; line-height: 1.5; letter-spacing: -.16px; }\n.own-meta .mt-testi figcaption { display: flex; align-items: center; gap: 12px; margin-top: 22px; font-size: 14px; color: var(--steel); }\n.own-meta .mt-testi figcaption b { color: var(--ink); }\n.own-meta .mt-avatar { display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%; background: var(--ink-deep); color: #fff; font-size: 13px; font-weight: 700; flex: none; }\n\n/* ── footer ──────────────────────────────────────────────────────────────── */\n.own-meta .mt-foot { border-top: 1px solid var(--hairline-soft); padding: clamp(40px, 5cqi, 64px) var(--gut); }\n.own-meta .mt-foot-top { display: grid; grid-template-columns: 220px 1fr; gap: 40px; }\n.own-meta .mt-foot-brand { display: flex; align-items: center; gap: 10px; }\n.own-meta .mt-foot-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }\n.own-meta .mt-foot-col h3 { font-size: 14px; font-weight: 700; letter-spacing: -.14px; margin-bottom: 14px; }\n.own-meta .mt-foot-col a { display: block; color: var(--steel); text-decoration: none; font-size: 14px; margin-bottom: 10px; }\n.own-meta .mt-foot-col a:hover { color: var(--ink); text-decoration: underline; }\n.own-meta .mt-foot-bottom { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-top: 44px; padding-top: 20px; border-top: 1px solid var(--hairline-soft); color: var(--stone); font-size: 12px; }\n.own-meta .mt-foot-links { display: flex; gap: 20px; }\n.own-meta .mt-foot-links a { color: var(--stone); text-decoration: none; }\n.own-meta .mt-foot-links a:hover { color: var(--ink); text-decoration: underline; }\n\n/* ── responsive ──────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-meta .mt-tabs { display: none; }\n  .own-meta .mt-icon-row { grid-template-columns: repeat(2, 1fr); }\n  .own-meta .mt-pdp-gallery { grid-template-columns: 72px minmax(0, 1fr); }\n  .own-meta .mt-buy { grid-column: 1 / -1; }\n  .own-meta .mt-thumb { width: 64px; height: 64px; }\n  .own-meta .mt-testi-grid { grid-template-columns: 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-meta .mt-nav { top: 10px; gap: 10px; padding: 10px 14px; }\n  .own-meta .mt-search { display: none; }\n  .own-meta .mt-hero, .own-meta .mt-pdp { margin-left: 12px; margin-right: 12px; }\n  .own-meta .mt-hero-overlay { padding: 28px 22px; }\n  .own-meta .mt-photo-grid { grid-template-columns: 1fr; }\n  .own-meta .mt-pdp-gallery { grid-template-columns: 1fr; }\n  .own-meta .mt-thumbs { grid-auto-flow: column; grid-auto-columns: 64px; overflow-x: auto; }\n  .own-meta .mt-foot-top { grid-template-columns: 1fr; gap: 28px; }\n  .own-meta .mt-foot-grid { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 430px) {\n  .own-meta .mt-icon-row, .own-meta .mt-foot-grid { grid-template-columns: 1fr; }\n  .own-meta .mt-pdp-screen { grid-template-columns: 1fr; }\n  .own-meta .mt-pdp-side { display: none; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-meta *, .own-meta *::before, .own-meta *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — Meta own-layout behaviour ═════════════════════════════════
   Registers window.OWN_LAYOUTS['meta'].init(root). Keeps the PDP interactive:
   gallery thumbnails, plan radios and the cart button update a small summary.
   Returns a cleanup removing every listener. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['meta'] = {
    init: function (root) {
      var thumbs = Array.prototype.slice.call(root.querySelectorAll('.mt-thumb'));
      var radios = Array.prototype.slice.call(root.querySelectorAll('input[name="mtPlan"]'));
      var swatches = Array.prototype.slice.call(root.querySelectorAll('.mt-swatch'));
      var cart = root.querySelector('[data-cart]');
      var priceEl = root.querySelector('.mt-price');

      function onThumb(e) {
        thumbs.forEach(function (t) { t.classList.toggle('is-active', t === e.currentTarget); });
      }
      function onSwatch(e) {
        swatches.forEach(function (s) { s.classList.toggle('is-on', s === e.currentTarget); });
      }
      function onRadio() {
        var checked = radios.filter(function (r) { return r.checked; })[0];
        var price = checked && checked.getAttribute('data-price');
        if (!price || !priceEl) return;
        priceEl.textContent = '';
        var amt = document.createElement('b');
        amt.textContent = price;
        var sfx = document.createElement('span');
        sfx.textContent = ' /mo per site';
        priceEl.appendChild(amt);
        priceEl.appendChild(sfx);
      }
      function onCart() {
        if (!cart) return;
        var prev = cart.textContent;
        cart.textContent = 'Added \u2713';
        setTimeout(function () { if (cart) cart.textContent = prev; }, 1400);
      }

      thumbs.forEach(function (t) { t.addEventListener('click', onThumb); });
      swatches.forEach(function (s) { s.addEventListener('click', onSwatch); });
      radios.forEach(function (r) { r.addEventListener('change', onRadio); });
      if (cart) cart.addEventListener('click', onCart);

      return function cleanup() {
        thumbs.forEach(function (t) { t.removeEventListener('click', onThumb); });
        swatches.forEach(function (s) { s.removeEventListener('click', onSwatch); });
        radios.forEach(function (r) { r.removeEventListener('change', onRadio); });
        if (cart) cart.removeEventListener('click', onCart);
      };
    }
  };
})();
